import * as T from './vendor/three/three.module.js';
// Proportions referenced to the north and south photographic elevations (see assets/arrival/SOURCES.md).
export function createDongwuGate(){
 const group=new T.Group(),stone=new T.MeshStandardMaterial({color:0xd5d0c2,roughness:.93}),trim=new T.MeshStandardMaterial({color:0xbab8ab,roughness:.86}),iron=new T.MeshStandardMaterial({color:0x323b37,metalness:.65,roughness:.6});
 const noise=document.createElement('canvas');noise.width=noise.height=256;const ctx=noise.getContext('2d'),pixels=ctx.createImageData(256,256);let seed=73;const random=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);for(let i=0;i<pixels.data.length;i+=4){const n=220+random()*30;pixels.data.set([n,n,n,255],i);}ctx.putImageData(pixels,0,0);const texture=new T.CanvasTexture(noise);texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.repeat.set(3,4);stone.map=texture;stone.bumpMap=texture;stone.bumpScale=.018;
 function box(x,y,z,w,h,d,mat=stone){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;group.add(m);return m;}
 function arch(cx,r,spring,top,half){const shape=new T.Shape();shape.moveTo(cx-half,0);shape.lineTo(cx-r,0);shape.lineTo(cx-r,spring);shape.absarc(cx,spring,r,Math.PI,0,true);shape.lineTo(cx+r,0);shape.lineTo(cx+half,0);shape.lineTo(cx+half,top);shape.lineTo(cx-half,top);shape.closePath();const m=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:.5,bevelEnabled:true,bevelSegments:1,steps:1,bevelSize:.025,bevelThickness:.025,curveSegments:40}),stone);m.position.z=-.25;m.castShadow=m.receiveShadow=true;group.add(m);
  const points=[];for(let i=0;i<=48;i++){const a=Math.PI-i*Math.PI/48;points.push(new T.Vector3(cx+r*Math.cos(a),spring+r*Math.sin(a),.28));}const edge=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points),48,.038,5,false),trim);group.add(edge);
 }
 arch(0,1.55,2.9,6.15,2.25);arch(-3.2,.82,2.2,3.8,1.2);arch(3.2,.82,2.2,3.8,1.2);
 for(const x of [-1.95,1.95]){box(x,2.75,.1,.64,5.5,.8);box(x,.18,.12,.84,.36,.9,trim);for(const [y,w,h]of [[4.3,.84,.12],[4.46,.92,.13],[4.57,1,.09],[5.91,.85,.12],[6.04,.96,.11]])box(x,y,.1,w,h,.94,trim);}
 for(const [y,w,h]of [[6.16,4.65,.16],[6.3,4.88,.12],[6.4,5,.12]])box(0,y,0,w,h,.85,trim);
 for(const side of [-1,1]){box(side*3.35,3.8,0,2.3,.16,.75,trim);const curve=new T.CatmullRomCurve3([new T.Vector3(side*2.3,4.3,0),new T.Vector3(side*2.75,3.94,0),new T.Vector3(side*3.2,3.86,0)]);group.add(new T.Mesh(new T.TubeGeometry(curve,20,.085,6,false),trim));box(side*6.7,1.5,0,4.5,3,.42);box(side*6.7,3.04,0,4.65,.16,.62,trim);}
 const sign=document.createElement('canvas');sign.width=1024;sign.height=240;const c=sign.getContext('2d');c.fillStyle='#d5d0c2';c.fillRect(0,0,1024,240);c.strokeStyle='#b8b5a8';c.lineWidth=8;c.strokeRect(4,4,1016,232);c.fillStyle='#262d2b';c.textAlign='center';c.textBaseline='middle';c.font='148px KaiTi,STKaiti,serif';c.fillText('學 大 吳 東',512,127);const plaque=new T.Mesh(new T.PlaneGeometry(2.75,.65),new T.MeshStandardMaterial({map:new T.CanvasTexture(sign),roughness:1}));plaque.position.set(0,5.3,.52);group.add(plaque);
 // Chinese motto is carved on the campus-facing pillars, as documented by Soochow University.
 for(const [x,text]of [[1.95,'養天地正氣'],[-1.95,'法古今完人']]){const cv=document.createElement('canvas');cv.width=256;cv.height=1536;const pen=cv.getContext('2d');pen.fillStyle='#d5d0c2';pen.fillRect(0,0,256,1536);pen.fillStyle='#343932';pen.textAlign='center';pen.textBaseline='middle';pen.font='160px KaiTi,STKaiti,serif';[...text].forEach((char,i)=>pen.fillText(char,128,200+i*270));const map=new T.CanvasTexture(cv);map.colorSpace=T.SRGBColorSpace;const inscription=new T.Mesh(new T.PlaneGeometry(.43,2.65),new T.MeshStandardMaterial({map,roughness:1}));inscription.position.set(x,2.75,-.315);inscription.rotation.y=Math.PI;inscription.name='dongwu-motto-'+text;group.add(inscription);}
 // Two hinged iron leaves open physically into the grounds.
 const leaves=[];for(const side of [-1,1]){const leaf=new T.Group();leaf.position.set(side*1.52,0,.06);group.add(leaf);const direction=-side;for(let i=0;i<=10;i++){const x=direction*i*.15,worldX=side*1.52+x,h=2.9+Math.sqrt(Math.max(0,1.55**2-worldX**2))-.06;const bar=new T.Mesh(new T.CylinderGeometry(.012,.012,h,5),iron);bar.position.set(x,h/2,0);leaf.add(bar);if(i<10){for(const y of [.42,2.3]){const curl=new T.Mesh(new T.TorusGeometry(.065,.009,4,14),iron);curl.position.set(x+direction*.075,y,0);leaf.add(curl);}}}for(const y of [.15,.7,2.25]){const bar=new T.Mesh(new T.BoxGeometry(1.52,.035,.035),iron);bar.position.set(direction*.76,y,0);leaf.add(bar);}leaves.push({leaf,side});}
 return{group,open(p){for(const{leaf,side}of leaves)leaf.rotation.y=side*p*1.45;}};
}
